final class PrimsMinimumSpanningTree implements MinimumSpanningTreeAlgorithm {
    private static final int START_VERTEX = 0;

    @Override
    public MstResult compute(Graph graph) {
        PrimVertexState vertexState = new PrimVertexState(graph.vertexCount(), START_VERTEX);

        for (int visitedVertices = 0; visitedVertices < graph.vertexCount(); visitedVertices++) {
            int currentVertex = vertexState.nextVertexToInclude();
            if (currentVertex == -1) {
                throw new IllegalStateException("Graph must be connected.");
            }

            vertexState.include(currentVertex);
            relaxAdjacentVertices(graph, currentVertex, vertexState);
        }

        return vertexState.buildResult();
    }

    private static void relaxAdjacentVertices(Graph graph, int currentVertex, PrimVertexState vertexState) {
        for (Neighbor neighbor : graph.neighborsOf(currentVertex)) {
            int candidateVertex = neighbor.vertex();
            if (vertexState.isIncluded(candidateVertex)) {
                continue;
            }

            vertexState.considerEdge(currentVertex, candidateVertex, neighbor.weight());
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

final class PrimVertexState {
    private static final int NO_PARENT = -1;

    private final int[] parentByVertex;
    private final int[] bestWeightByVertex;
    private final boolean[] includedVertices;

    PrimVertexState(int vertexCount, int startVertex) {
        parentByVertex = new int[vertexCount];
        bestWeightByVertex = new int[vertexCount];
        includedVertices = new boolean[vertexCount];

        Arrays.fill(parentByVertex, NO_PARENT);
        Arrays.fill(bestWeightByVertex, Integer.MAX_VALUE);
        bestWeightByVertex[startVertex] = 0;
    }

    int nextVertexToInclude() {
        int lightestWeight = Integer.MAX_VALUE;
        int selectedVertex = -1;

        for (int vertex = 0; vertex < includedVertices.length; vertex++) {
            if (!includedVertices[vertex] && bestWeightByVertex[vertex] < lightestWeight) {
                lightestWeight = bestWeightByVertex[vertex];
                selectedVertex = vertex;
            }
        }

        return selectedVertex;
    }

    void include(int vertex) {
        includedVertices[vertex] = true;
    }

    boolean isIncluded(int vertex) {
        return includedVertices[vertex];
    }

    void considerEdge(int fromVertex, int toVertex, int weight) {
        if (weight < bestWeightByVertex[toVertex]) {
            parentByVertex[toVertex] = fromVertex;
            bestWeightByVertex[toVertex] = weight;
        }
    }

    MstResult buildResult() {
        List<Edge> edges = new ArrayList<>();

        for (int vertex = 1; vertex < parentByVertex.length; vertex++) {
            int parentVertex = parentByVertex[vertex];
            if (parentVertex == NO_PARENT) {
                throw new IllegalStateException("Graph must be connected.");
            }

            edges.add(new Edge(parentVertex, vertex, bestWeightByVertex[vertex]));
        }

        return MstResult.fromEdges(edges);
    }
}

final class MstApplication {
    private final AdjacencyMatrixSource adjacencyMatrixSource;
    private final GraphFactory graphFactory;
    private final MinimumSpanningTreeAlgorithm algorithm;
    private final MstResultFormatter formatter;

    MstApplication(
            AdjacencyMatrixSource adjacencyMatrixSource,
            GraphFactory graphFactory,
            MinimumSpanningTreeAlgorithm algorithm,
            MstResultFormatter formatter) {
        this.adjacencyMatrixSource = adjacencyMatrixSource;
        this.graphFactory = graphFactory;
        this.algorithm = algorithm;
        this.formatter = formatter;
    }

    String run() {
        AdjacencyMatrix adjacencyMatrix = adjacencyMatrixSource.load();
        Graph graph = graphFactory.create(adjacencyMatrix);
        MstResult result = algorithm.compute(graph);
        return formatter.format(result);
    }
}

import java.util.ArrayList;
import java.util.List;

final class NeighborListGraph implements Graph {
    private final List<List<Neighbor>> neighborsByVertex;

    private NeighborListGraph(List<List<Neighbor>> neighborsByVertex) {
        this.neighborsByVertex = copyNeighbors(neighborsByVertex);
    }

    static Graph fromAdjacencyMatrix(AdjacencyMatrix adjacencyMatrix) {
        List<List<Neighbor>> neighborsByVertex = new ArrayList<>(adjacencyMatrix.vertexCount());

        for (int vertex = 0; vertex < adjacencyMatrix.vertexCount(); vertex++) {
            neighborsByVertex.add(adjacencyMatrix.neighborsOf(vertex));
        }

        return new NeighborListGraph(neighborsByVertex);
    }

    @Override
    public int vertexCount() {
        return neighborsByVertex.size();
    }

    @Override
    public List<Neighbor> neighborsOf(int vertex) {
        return neighborsByVertex.get(vertex);
    }

    private static List<List<Neighbor>> copyNeighbors(List<List<Neighbor>> neighborsByVertex) {
        List<List<Neighbor>> copiedNeighbors = new ArrayList<>(neighborsByVertex.size());

        for (List<Neighbor> neighbors : neighborsByVertex) {
            copiedNeighbors.add(List.copyOf(neighbors));
        }

        return List.copyOf(copiedNeighbors);
    }
}

